{"summary": "Escalate tickets that report an outage.",
"rules": [
{"condition": {"op": "subject_has", "terms": ["outage", "service down", "cannot log in"]}, "action": "escalate", "weight": 6, "note": "Outages go to the on-call team first"}
]}

{"summary": "Escalate urgent tickets from enterprise customers.",
"rules": [
{"match": "all", "predicates": [{"op": "from_domain_in", "domains": ["enterprise.example.com"]}, {"op": "priority_in", "codes": ["p1", "p2"]}], "action": "escalate", "weight": 6, "note": "Enterprise SLA"}
]}

{"summary": "Deprioritize very large messages by archiving them for manual review.",
"rules": [
{"condition": {"op": "size_range", "min": 10240, "max": 51200}, "action": "archive", "weight": 2, "note": "Large attachments are reviewed in batches"}
]}

{"summary": "Escalate tickets nobody answered for two days.",
"rules": [
{"condition": {"op": "age_range", "since": "last_reply", "min": 48}, "action": "escalate", "weight": 5, "note": "Hours since the last customer reply"}
]}

{"summary": "Escalate outages, label refunds, archive auto-replies.",
"rules": [
{"condition": {"op": "subject_has", "terms": ["outage"]}, "action": "escalate", "weight": 6},
{"condition": {"op": "body_has", "terms": ["refund"]}, "action": "label", "label": "billing", "weight": 3},
{"condition": {"op": "subject_has", "terms": ["automatic reply", "out of office"]}, "action": "archive", "weight": 1, "note": "Auto-replies need no answer"}
]
}
